/**
 * Shared types for Millionaire Quiz. FROZEN after WP0 - do not edit in other work packages.
 * Pure type module: no runtime code, no imports.
 */

// ---------------------------------------------------------------- Questions & banks
export type AnswerIndex = 0 | 1 | 2 | 3;
export type Difficulty = 1 | 2 | 3 | 4 | 5;
export type Answers = [string, string, string, string];

export interface Question {
  id: string;
  text: string;
  answers: Answers;
  correct: AnswerIndex;
  difficulty: Difficulty;
  category?: string;
  explanation?: string;
  reviewed?: boolean;
}

export type Edition = 'US' | 'UK' | 'AU' | 'INT';
export type Provenance = 'episode-style' | 'transcribed';

export interface QuestionBank {
  schemaVersion: 1;
  id: string;
  name: string;
  episode: number;
  /** ISO date "YYYY-MM-DD" - displayed as "Style era". */
  date: string;
  edition: Edition;
  provenance: Provenance;
  sources?: string[];
  tags?: string[];
  /** Exactly 15 questions. */
  questions: Question[];
  /** At least 3 spares. */
  spares: Question[];
}

/** Lightweight manifest entry for the library (generated by scripts/build-manifest.ts). */
export interface BankMeta {
  id: string;
  name: string;
  episode: number;
  date: string;
  edition: Edition;
  provenance: Provenance;
  tags: string[];
  questionCount: number;
  spareCount: number;
  /** Distinct difficulties present, e.g. [1,2,3,4,5]. */
  difficulties: Difficulty[];
}

export interface BankFilter {
  query?: string;
  edition?: Edition;
  difficulty?: Difficulty;
  tag?: string;
}

// ---------------------------------------------------------------- Ladder & timer
export type Currency = '$' | '£' | '€' | 'pts';

export interface LadderConfig {
  id: string;
  name: string;
  currency: Currency;
  /** 1..20 strictly increasing prizes. */
  prizes: number[];
  /** 0-based question indices that are safe havens. */
  safeHavens: number[];
  topPrizeLabel?: string;
}

export type TimerConfig =
  | { mode: 'off' }
  | {
      mode: 'clock';
      /** Seconds per question; indexed by qIndex (length should equal ladder length). */
      secondsPerQuestion: number[];
      bankUnusedToLast: boolean;
      onTimeout: 'walk' | 'lose';
    };

// ---------------------------------------------------------------- Lifelines
export type EffectType =
  | 'remove-wrong'
  | 'friend-hint'
  | 'audience-poll'
  | 'skip-question'
  | 'second-chance'
  | 'extra-time'
  | 'host-hint';

export interface LifelineParams {
  /** remove-wrong: how many wrong answers to remove (<= 2). */
  n?: number;
  /** friend-hint / audience-poll / host-hint: 0..1 accuracy override. */
  accuracy?: number;
  /** extra-time: seconds to add (5..120). */
  seconds?: number;
}

export interface LifelineDef {
  id: string;
  name: string;
  icon: string;
  effect: EffectType;
  params: LifelineParams;
  /** Max uses per game. */
  uses: number;
  /** 0-based question index from which the lifeline is available. */
  availableFromQ?: number;
  builtIn: boolean;
}

export interface Hint {
  /** Suggested answer index, or null if the helper does not know. */
  answer: number | null;
  /** 0..1 */
  confidence: number;
  text: string;
}

export interface EffectResult {
  eliminate?: number[];
  /** Percentages per answer, sums to 100, 0 for eliminated. */
  poll?: number[];
  hint?: Hint;
  replaceQuestion?: Question;
  addTimeMs?: number;
  armSecondChance?: true;
}

// ---------------------------------------------------------------- Game config / custom games
export interface GameConfig {
  /** Questions in ladder order; length must equal ladder.prizes.length. */
  questions: Question[];
  spares: Question[];
  ladder: LadderConfig;
  lifelines: LifelineDef[];
  timer: TimerConfig;
  shuffleAnswers: boolean;
  seed: number;
  sourceBankId?: string;
  customGameId?: string;
}

export interface CustomGame {
  id: string;
  name: string;
  /** ISO timestamp */
  createdAt: string;
  /** ISO timestamp */
  updatedAt: string;
  questions: Question[];
  spares: Question[];
  ladder: LadderConfig;
  /** Ids of lifelines (built-in or custom) enabled for this game. */
  lifelineIds: string[];
  timer: TimerConfig;
}

export interface ExportFile {
  format: 'millionaire-custom';
  version: 1;
  games: CustomGame[];
  lifelines: LifelineDef[];
  /** Locally flagged question ids ("Report question"). */
  flaggedQuestionIds?: string[];
}

// ---------------------------------------------------------------- Game state machine
export type Phase =
  | 'INTRO'
  | 'PRESENTING'
  | 'AWAITING'
  | 'LIFELINE'
  | 'CONFIRMING'
  | 'LOCKED'
  | 'CORRECT'
  | 'WRONG'
  | 'MILESTONE'
  | 'WALK_CONFIRM'
  | 'WON'
  | 'GAME_OVER';

export type GameOutcome = 'won' | 'walked' | 'wrong' | 'timeout';

export type GameEvent =
  | { type: 'START' }
  | { type: 'ANSWERS_REVEALED' }
  | { type: 'USE_LIFELINE'; lifelineId: string }
  | { type: 'LIFELINE_DONE' }
  | { type: 'SELECT'; index: AnswerIndex }
  | { type: 'CANCEL' }
  | { type: 'FINAL_ANSWER' }
  | { type: 'REVEAL' }
  | { type: 'NEXT' }
  | { type: 'WALK_AWAY' }
  | { type: 'CONFIRM' }
  | { type: 'TIMEOUT' }
  /** Clock tick; dtMs elapsed since last tick (UI timer drives this). */
  | { type: 'TICK'; dtMs: number };

export interface ActiveEffects {
  secondChanceArmed: boolean;
  /** True once the second chance has been consumed by a first wrong answer on this question. */
  secondChanceUsedOnQuestion: boolean;
  audiencePoll?: number[];
  friendHint?: Hint;
  hostHint?: Hint;
}

export interface GameLogEntry {
  /** ms since startedAt (or event counter if no clock available) */
  t: number;
  type: string;
  qIndex: number;
  detail?: string;
}

export interface GameState {
  phase: Phase;
  config: GameConfig;
  /** 0-based index of the current question. */
  qIndex: number;
  /** Current question as presented (answers possibly shuffled, `correct` remapped). */
  current: Question;
  /** Eliminated answer indices on the current question. */
  eliminated: number[];
  /** Currently selected answer (CONFIRMING / LOCKED / CORRECT / WRONG). */
  selected?: AnswerIndex;
  /** Uses consumed per lifeline id. */
  lifelineUses: Record<string, number>;
  /** Lifeline currently being resolved (phase LIFELINE). */
  activeLifelineId?: string;
  /** Result of the most recent lifeline use, for the UI to display. */
  lastEffect?: EffectResult;
  activeEffects: ActiveEffects;
  /** Remaining ms for current question (clock mode). */
  timeLeftMs?: number;
  /** Banked unused ms carried to the last question (clock mode with bankUnusedToLast). */
  bankedMs: number;
  usedSpareIds: string[];
  /** Epoch ms when the game started. */
  startedAt: number;
  /** Serialisable RNG position so a resumed game stays deterministic. */
  rngState?: number;
  outcome?: GameOutcome;
  /** Final winnings once phase is WON / GAME_OVER. */
  winnings?: number;
  /** Lifeline ids used during the game, in order. */
  lifelinesUsed: string[];
  log: GameLogEntry[];
}

// ---------------------------------------------------------------- Persistence
export type ReducedMotion = 'system' | 'on' | 'off';

export interface Settings {
  muted: boolean;
  /** 0..1 */
  volume: number;
  reducedMotion: ReducedMotion;
  shuffleAnswers: boolean;
  defaultTimer: TimerConfig;
  hostCommentary: boolean;
  revealDelayMs: number;
}

export interface HistoryEntry {
  id: string;
  /** ISO timestamp */
  date: string;
  bankId?: string;
  customGameId?: string;
  /** 0-based index of the last question reached. */
  reachedQ: number;
  outcome: GameOutcome;
  winnings: number;
  lifelinesUsed: string[];
  durationMs: number;
  currency?: Currency;
}

export interface Stats {
  games: number;
  wins: number;
  walks: number;
  losses: number;
  timeouts: number;
  bestWinnings: number;
  totalWinnings: number;
  avgReachedQ: number;
  /** Count of games that reached each question index. */
  reachedHistogram: number[];
  lifelineUsage: Record<string, number>;
}

export interface SavedGame {
  version: 1;
  savedAt: string;
  state: GameState;
}

export interface ImportResult {
  imported: number;
  errors: string[];
}

// ---------------------------------------------------------------- Validation
export interface ValidationResult {
  ok: boolean;
  errors: string[];
  warnings: string[];
}

// ---------------------------------------------------------------- Audio
export type SoundCue =
  | 'select'
  | 'final'
  | 'correct'
  | 'wrong'
  | 'lifeline'
  | 'milestone'
  | 'tick'
  | 'win'
  | 'bed-start'
  | 'bed-stop';

export interface SoundApi {
  unlock(): void;
  play(cue: SoundCue): void;
  setMuted(muted: boolean): void;
  setVolume(volume: number): void;
}

// ---------------------------------------------------------------- App / router
export type ScreenId = 'menu' | 'setup' | 'game' | 'results' | 'editor' | 'stats' | 'settings';

/** Params passed via navigate(); kept in memory by the router (not encoded in the hash). */
export interface ScreenParams {
  /** setup: bank to play or custom game to play. */
  bankId?: string;
  customGameId?: string;
  /** setup: choose a random bank. */
  random?: boolean;
  /** game: fully built config to start. */
  config?: GameConfig;
  /** game: resume the saved game. */
  resume?: boolean;
  /** results: the finished game's state. */
  finalState?: GameState;
  /** editor: custom game to edit (omit for new). */
  editId?: string;
  [key: string]: unknown;
}

export interface AppContext {
  navigate(screen: ScreenId, params?: ScreenParams): void;
  getSettings(): Settings;
  updateSettings(patch: Partial<Settings>): Settings;
  sound: SoundApi;
  /** Polite (or assertive) aria-live announcement. */
  announce(message: string, assertive?: boolean): void;
  /** True when motion should be reduced (system pref + settings override). */
  reducedMotion(): boolean;
  /** Dev/test hooks parsed from the query string (?seed=1&bank=fixture). */
  devParams: { seed?: number; bank?: string };
}

export interface Screen {
  /** Render into root; return an unmount/cleanup function. */
  mount(root: HTMLElement, ctx: AppContext, params?: ScreenParams): () => void;
}
